//! Loads the packed tables in `data/convert/*.z` (generated by `tools/convert/post.py`).
//!
//! Every file is embedded with `include_bytes!` and inflated and parsed on first use (`LazyLock`); nothing is touched
//! at launcher start-up. Rows carry a `since`/`until` version window, and `java_blocks(version)` etc. return the rows
//! in force. [`BlockResolver::new`] and [`ItemResolver::new`] build ready-to-use engines from them.

use std::collections::HashMap;
use std::io::Read;
use std::sync::{Arc, LazyLock};

use flate2::read::ZlibDecoder;

use super::engine::{BlockMapping, BlockResolver, Flag, PivotInfo, StateGroup, StateInfo, StateMapping, TypeMapping};
use super::items::{ItemKind, ItemMapping, ItemResolver};
use super::tables::IdRow;
use super::{Edition, StateValue, Version};

macro_rules! packed {
    ($name:literal) => {
        include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/data/convert/", $name))
    };
}

fn inflate(bytes: &[u8]) -> String {
    let mut text = String::new();
    ZlibDecoder::new(bytes).read_to_string(&mut text).expect("embedded table data is valid zlib text");
    text
}

/// Data lines: not comments, not empty.
fn lines(text: &str) -> impl Iterator<Item = &str> {
    text.lines().filter(|l| !l.is_empty() && !l.starts_with('#'))
}

/// Shares one `Arc<str>` per distinct string.
#[derive(Default)]
struct Interner(HashMap<Box<str>, Arc<str>>);

impl Interner {
    fn get(&mut self, s: &str) -> Arc<str> {
        if let Some(a) = self.0.get(s) {
            return a.clone();
        }
        let a: Arc<str> = Arc::from(s);
        self.0.insert(s.into(), a.clone());
        a
    }
}

pub(crate) fn in_force(since: Option<Version>, until: Option<Version>, v: Version) -> bool {
    since.is_none_or(|s| v >= s) && until.is_none_or(|u| v < u)
}

fn version_opt(s: &str) -> Option<Version> {
    if s.is_empty() { None } else { Version::parse(s) }
}

// ---- rows ---------------------------------------------------------------------------------------------------------

/// How a row is entered: both directions (`B`), edition -> pivot only (`I`) or pivot -> edition only (`C`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RowKind {
    Both,
    ToPivot,
    FromPivot,
}

impl RowKind {
    fn parse(s: &str) -> RowKind {
        match s {
            "B" => RowKind::Both,
            "I" => RowKind::ToPivot,
            _ => RowKind::FromPivot,
        }
    }

    /// The matching `register*` flavour.
    pub fn flag(self) -> Flag {
        match self {
            RowKind::Both => Flag::Register,
            RowKind::ToPivot => Flag::DuplicateOutput,
            RowKind::FromPivot => Flag::DuplicateInput,
        }
    }
}

/// A block mapping row with its version window.
#[derive(Clone, Debug)]
pub struct BlockRow {
    pub kind: RowKind,
    pub since: Option<Version>,
    pub until: Option<Version>,
    pub id: Arc<str>,
    pub states: Vec<(Arc<str>, StateValue)>,
    pub ty: Arc<str>,
    pub pivot_states: Vec<(Arc<str>, Arc<str>)>,
    pub group: Option<Arc<str>>,
}

/// An item mapping row with its version window.
#[derive(Clone, Debug)]
pub struct ItemRow {
    pub kind: RowKind,
    pub since: Option<Version>,
    pub until: Option<Version>,
    pub id: Arc<str>,
    pub states: Vec<(Arc<str>, StateValue)>,
    pub item: ItemKind,
    pub props: Vec<(Arc<str>, Arc<str>)>,
}

#[derive(Debug, Default)]
pub struct BlockTable {
    pub rows: Vec<BlockRow>,
    /// `(since, until, group)` of the extra state group applied to every block.
    pub extras: Vec<(Option<Version>, Option<Version>, Arc<str>)>,
}

#[derive(Debug, Default)]
pub struct ItemTable {
    pub rows: Vec<ItemRow>,
}

fn parse_states(s: &str, i: &mut Interner) -> Vec<(Arc<str>, StateValue)> {
    if s.is_empty() {
        return Vec::new();
    }
    s.split(',')
        .map(|p| {
            let (k, v) = p.split_once('=').expect("state pair");
            (i.get(k), StateValue::parse_typed(v).expect("typed state value"))
        })
        .collect()
}

fn parse_pairs(s: &str, i: &mut Interner) -> Vec<(Arc<str>, Arc<str>)> {
    if s.is_empty() {
        return Vec::new();
    }
    s.split(',')
        .map(|p| {
            let (k, v) = p.split_once('=').expect("pair");
            (i.get(k), i.get(v))
        })
        .collect()
}

fn parse_blocks<'a>(lines: impl Iterator<Item = &'a str>) -> BlockTable {
    let mut i = Interner::default();
    let mut table = BlockTable::default();
    for l in lines {
        let f: Vec<&str> = l.split('\t').collect();
        if f[0] == "X" {
            table.extras.push((version_opt(f[1]), version_opt(f[2]), i.get(f[3])));
            continue;
        }
        table.rows.push(BlockRow {
            kind: RowKind::parse(f[0]),
            since: version_opt(f[1]),
            until: version_opt(f[2]),
            id: i.get(f[3]),
            states: parse_states(f[4], &mut i),
            ty: i.get(f[5]),
            pivot_states: parse_pairs(f[6], &mut i),
            group: if f[7] == "-" { None } else { Some(i.get(f[7])) },
        });
    }
    table
}

fn parse_items<'a>(lines: impl Iterator<Item = &'a str>) -> ItemTable {
    let mut i = Interner::default();
    let mut table = ItemTable::default();
    for l in lines {
        let f: Vec<&str> = l.split('\t').collect();
        table.rows.push(ItemRow {
            kind: RowKind::parse(f[0]),
            since: version_opt(f[1]),
            until: version_opt(f[2]),
            id: i.get(f[3]),
            states: parse_states(f[4], &mut i),
            item: ItemKind::parse(f[5]).expect("item kind"),
            props: parse_pairs(f[6], &mut i),
        });
    }
    table
}

/// Legacy files hold `@blocks` / `@items` sections.
fn section<'a>(text: &'a str, name: &str) -> impl Iterator<Item = &'a str> {
    let mut current = "";
    let mut out = Vec::new();
    for l in lines(text) {
        if let Some(s) = l.strip_prefix('@') {
            current = s;
        } else if current == name {
            out.push(l);
        }
    }
    out.into_iter()
}

static PIVOT: LazyLock<Arc<PivotInfo>> = LazyLock::new(|| {
    let text = inflate(packed!("pivot.z"));
    let mut info = PivotInfo::default();
    let mut i = Interner::default();
    for l in lines(&text) {
        let f: Vec<&str> = l.split('\t').collect();
        match f[0] {
            "S" => {
                info.states.insert(
                    i.get(f[1]),
                    StateInfo {
                        name: i.get(f[2]),
                        default: i.get(f[3]),
                        values: f[4].split(',').map(|v| i.get(v)).collect(),
                    },
                );
            }
            "T" => {
                let states = if f[2].is_empty() { Vec::new() } else { f[2].split(',').map(|s| i.get(s)).collect() };
                info.types.insert(i.get(f[1]), states);
            }
            _ => {}
        }
    }
    Arc::new(info)
});

/// The pivot's states and block types (from Chunker's `VanillaBlockStates` and `ChunkerVanillaBlockType`).
pub fn pivot() -> Arc<PivotInfo> {
    PIVOT.clone()
}

static JAVA_BLOCKS: LazyLock<BlockTable> = LazyLock::new(|| parse_blocks(lines(&inflate(packed!("java_blocks.z")))));
static BEDROCK_BLOCKS: LazyLock<BlockTable> =
    LazyLock::new(|| parse_blocks(lines(&inflate(packed!("bedrock_blocks.z")))));
static JAVA_LEGACY: LazyLock<(BlockTable, ItemTable)> = LazyLock::new(|| {
    let text = inflate(packed!("java_legacy.z"));
    (parse_blocks(section(&text, "blocks")), parse_items(section(&text, "items")))
});
static BEDROCK_LEGACY: LazyLock<BlockTable> = LazyLock::new(|| {
    let text = inflate(packed!("bedrock_legacy.z"));
    parse_blocks(section(&text, "blocks"))
});
static JAVA_ITEMS: LazyLock<ItemTable> = LazyLock::new(|| parse_items(lines(&inflate(packed!("java_items.z")))));
static BEDROCK_ITEMS: LazyLock<ItemTable> = LazyLock::new(|| parse_items(lines(&inflate(packed!("bedrock_items.z")))));

/// The block rows in force at one version.
#[derive(Debug)]
pub struct BlockRows {
    pub rows: Vec<&'static BlockRow>,
    /// The extra state group applied to every block (Bedrock `WATERLOGGED`, Java `DEFAULT_WATERLOGGED_FALSE`).
    pub extra: Option<&'static str>,
}

fn block_rows(table: &'static BlockTable, v: Version) -> BlockRows {
    BlockRows {
        rows: table.rows.iter().filter(|r| in_force(r.since, r.until, v)).collect(),
        extra: table.extras.iter().find(|e| in_force(e.0, e.1, v)).map(|e| &*e.2),
    }
}

fn item_rows(table: &'static ItemTable, v: Version) -> Vec<&'static ItemRow> {
    table.rows.iter().filter(|r| in_force(r.since, r.until, v)).collect()
}

/// Java block rows (modern, flattened ids, 1.13 and later) in force at `v`.
pub fn java_blocks(v: Version) -> BlockRows {
    block_rows(&JAVA_BLOCKS, v)
}

/// Bedrock block rows (named states, 1.13 and later) in force at `v`.
pub fn bedrock_blocks(v: Version) -> BlockRows {
    block_rows(&BEDROCK_BLOCKS, v)
}

/// Java legacy (numeric `data`, before 1.13) block rows.
pub fn java_legacy_blocks(v: Version) -> BlockRows {
    block_rows(&JAVA_LEGACY.0, v)
}

/// Bedrock legacy (numeric `data`, 1.12 and older palettes) block rows.
pub fn bedrock_legacy_blocks(v: Version) -> BlockRows {
    block_rows(&BEDROCK_LEGACY, v)
}

/// Java item rows in force at `v` (block items are not listed: they fall through to the block table).
pub fn java_items(v: Version) -> Vec<&'static ItemRow> {
    item_rows(&JAVA_ITEMS, v)
}

pub fn bedrock_items(v: Version) -> Vec<&'static ItemRow> {
    item_rows(&BEDROCK_ITEMS, v)
}

pub fn java_legacy_items(v: Version) -> Vec<&'static ItemRow> {
    item_rows(&JAVA_LEGACY.1, v)
}

// ---- state groups -------------------------------------------------------------------------------------------------

/// All state groups of an edition by name (`legacy:` prefix for the legacy ones).
pub type GroupDefs = HashMap<Arc<str>, Arc<StateGroup>>;

fn parse_value_list(s: &str) -> Option<Vec<StateValue>> {
    if s == "~" {
        return None;
    }
    s.split('|').map(StateValue::parse_typed).collect()
}

fn parse_groups(text: &str) -> GroupDefs {
    let mut i = Interner::default();
    // Pass 1: type mappings.
    let mut types: HashMap<Arc<str>, Arc<TypeMapping>> = HashMap::new();
    let mut cur: Option<(Arc<str>, TypeMapping)> = None;
    for l in lines(text) {
        let f: Vec<&str> = l.split('\t').collect();
        match f[0] {
            "T" => {
                if let Some((n, t)) = cur.take() {
                    types.insert(n, Arc::new(t));
                }
                cur = Some((i.get(f[1]), TypeMapping::new()));
            }
            "B" | "M" | "R" | "D" if cur.is_some() => {
                let t = &mut cur.as_mut().expect("in a type").1;
                let (Some(ins), outs) = (parse_value_list(f[1]), f[2]) else { continue };
                if outs == "~" {
                    continue;
                }
                let outs: Vec<Arc<str>> = outs.split('|').map(|o| i.get(o)).collect();
                match f[0] {
                    "D" => t.defaults(ins, outs),
                    "B" => {
                        t.input_to_output.insert(ins.clone(), outs.clone());
                        t.output_to_input.insert(outs, ins);
                    }
                    "M" => {
                        t.input_to_output.insert(ins, outs);
                    }
                    _ => {
                        t.output_to_input.insert(outs, ins);
                    }
                }
            }
            "G" => {
                if let Some((n, t)) = cur.take() {
                    types.insert(n, Arc::new(t));
                }
            }
            _ => {}
        }
    }
    if let Some((n, t)) = cur.take() {
        types.insert(n, Arc::new(t));
    }
    // Pass 2: groups.
    let mut groups = GroupDefs::new();
    let mut cur: Option<(Arc<str>, StateGroup)> = None;
    for l in lines(text) {
        let f: Vec<&str> = l.split('\t').collect();
        match f[0] {
            "G" => {
                if let Some((n, g)) = cur.take() {
                    groups.insert(n, Arc::new(g));
                }
                cur = Some((i.get(f[1]), StateGroup::default()));
            }
            "T" => {
                if let Some((n, g)) = cur.take() {
                    groups.insert(n, Arc::new(g));
                }
            }
            "S" if cur.is_some() => {
                let ty = types.get(f[3]).unwrap_or_else(|| panic!("type mapping {} missing", f[3])).clone();
                let split = |s: &str, i: &mut Interner| -> Vec<Arc<str>> { s.split(',').map(|n| i.get(n)).collect() };
                cur.as_mut().expect("in a group").1.states.push(StateMapping {
                    input_names: split(f[1], &mut i),
                    output_states: split(f[2], &mut i),
                    ty,
                });
            }
            "DI" if cur.is_some() => {
                let v = StateValue::parse_typed(f[2]).expect("default input");
                cur.as_mut().expect("in a group").1.default_inputs.insert(i.get(f[1]), v);
            }
            "DO" if cur.is_some() => {
                cur.as_mut().expect("in a group").1.default_outputs.insert(i.get(f[1]), i.get(f[2]));
            }
            _ => {}
        }
    }
    if let Some((n, g)) = cur.take() {
        groups.insert(n, Arc::new(g));
    }
    groups
}

static JAVA_GROUPS: LazyLock<GroupDefs> = LazyLock::new(|| parse_groups(&inflate(packed!("java_groups.z"))));
static BEDROCK_GROUPS: LazyLock<GroupDefs> = LazyLock::new(|| parse_groups(&inflate(packed!("bedrock_groups.z"))));

/// The state groups of an edition.
pub fn groups(edition: Edition) -> &'static GroupDefs {
    match edition {
        Edition::Java => &JAVA_GROUPS,
        Edition::Bedrock => &BEDROCK_GROUPS,
    }
}

// ---- simple id tables ---------------------------------------------------------------------------------------------

fn parse_ids(text: &str) -> Vec<IdRow> {
    let mut i = Interner::default();
    lines(text)
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            IdRow {
                table: i.get(f[0]),
                kind: f[1].as_bytes()[0],
                since: version_opt(f[2]),
                until: version_opt(f[3]),
                a: i.get(f[4]),
                b: i.get(f[5]),
            }
        })
        .collect()
}

static JAVA_IDS: LazyLock<Vec<IdRow>> = LazyLock::new(|| parse_ids(&inflate(packed!("java_misc.z"))));
static BEDROCK_IDS: LazyLock<Vec<IdRow>> = LazyLock::new(|| parse_ids(&inflate(packed!("bedrock_misc.z"))));

pub(crate) fn id_rows(edition: Edition) -> &'static [IdRow] {
    match edition {
        Edition::Java => &JAVA_IDS,
        Edition::Bedrock => &BEDROCK_IDS,
    }
}

// ---- resolvers from data ------------------------------------------------------------------------------------------

fn build_blocks(rows: BlockRows, groups: &GroupDefs) -> BlockResolver {
    let mut r = BlockResolver::empty(pivot());
    if let Some(extra) = rows.extra {
        r.extra_group(groups.get(extra).unwrap_or_else(|| panic!("extra group {extra} missing")).clone());
    }
    for row in rows.rows {
        let mut m = BlockMapping::of(&row.id, &row.ty);
        m.states = row.states.iter().cloned().collect();
        m.pivot_states = row.pivot_states.iter().cloned().collect();
        if let Some(g) = &row.group {
            m.group = Some(groups.get(g).unwrap_or_else(|| panic!("state group {g} missing")).clone());
        }
        r.register(row.kind.flag(), m).expect("generated tables have no conflicts");
    }
    r
}

fn build_items(rows: Vec<&'static ItemRow>, default_data: bool) -> ItemResolver {
    let mut r = ItemResolver::empty(pivot(), default_data);
    for row in rows {
        let mut m = ItemMapping::of(&row.id, row.item.clone());
        m.states = row.states.iter().cloned().collect();
        m.props = row.props.iter().cloned().collect();
        r.register(row.kind.flag(), m).expect("generated tables have no conflicts");
    }
    r
}

impl BlockResolver {
    /// The modern block table of `edition` at `version` (Java 1.13+ ids, Bedrock named states).
    pub fn new(edition: Edition, version: Version) -> BlockResolver {
        match edition {
            Edition::Java => build_blocks(java_blocks(version), groups(edition)),
            Edition::Bedrock => build_blocks(bedrock_blocks(version), groups(edition)),
        }
    }

    /// The legacy block table (numeric `data` as the state `data`).
    pub fn new_legacy(edition: Edition, version: Version) -> BlockResolver {
        match edition {
            Edition::Java => build_blocks(java_legacy_blocks(version), groups(edition)),
            Edition::Bedrock => build_blocks(bedrock_legacy_blocks(version), groups(edition)),
        }
    }
}

impl ItemResolver {
    /// The modern item table of `edition` at `version`.
    pub fn new(edition: Edition, version: Version) -> ItemResolver {
        match edition {
            Edition::Java => build_items(java_items(version), false),
            Edition::Bedrock => build_items(bedrock_items(version), false),
        }
    }

    /// The legacy Java item table (`data` as damage; written items get `data=0` when unset).
    pub fn new_legacy_java(version: Version) -> ItemResolver {
        build_items(java_legacy_items(version), true)
    }
}
